    close("flex.breach", r.flex.breach, 639.5300232768059);
    close("flex.energy_cost", r.flex.energy_cost, 21898202.013520163);
    close("flex.max_gap", r.flex.max_gap, 16.3215194940567);
    close("flex.catch_e", r.flex.catch_e, 920.24674500525);
